"""Render docs/DOC_TYPE_V2_1_AUDIT_AND_BASELINE.md from the measured JSON reports (audit_v2_1.json, validation_v2_1.json, tfidf_baseline_v2_1.json, synthetic_in_phash.json, doc_type_v2_1_stats.json). Numbers are never typed by hand."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2]; R = ROOT / "reports/doc_type"; J = lambda p: json.loads(Path(p).read_text())
au, va, bl, si, st = J(R / "audit_v2_1.json"), J(R / "validation_v2_1.json"), J(R / "experiments_v3/tfidf_baseline_v2_1.json"), J(R / "experiments_v3/synthetic_in_phash.json"), J(ROOT / "datasets/metadata/doc_type_v2_1_stats.json")
E, D, C = bl["experiments"], bl["diagnostics"], bl["counts"]; L = []; w = L.append
def table(head, rows): w("| " + " | ".join(head) + " |"); w("|" + "---|" * len(head)); [w("| " + " | ".join(str(x) for x in r) + " |") for r in rows]
w("# Document-type dataset v2.1: audit, split correction and TF-IDF feasibility baseline\n\nGenerated by `scripts/dataset_discovery/write_v2_1_report.py` from the JSON reports in `reports/doc_type/`. Development experiment only - **no real-world accuracy is claimed for any class that has no approved real labelled examples.**\n")
w("## 1. Integrity audit (`reports/doc_type/audit_v2_1.json`, `validation_v2_1.json`)\n")
A = au["A_files"]; B = au["B_separation_and_approval"]; Dp = au["D_protected"]
table(["check", "result"], [["manifest rows / page files", f"{A['rows']} / {A['page_files']}"], ["missing files / checksum mismatches (every page hashed)", f"{A['missing_files']} / {A['checksum_mismatch']}"], ["unique doc_id / unique document sha256", f"{A['unique_doc_ids']} / {A['unique_doc_sha256']}"],
    ["synthgen_v1 index rows = manifest rows; files on disk", f"{A['per_source']['synthgen_v1']['index_rows']} = {A['per_source']['synthgen_v1']['rows']}; {A['per_source']['synthgen_v1']['files_on_disk']} page files (176 extra pages of multi-page docs)"],
    ["Agami PDFs / FATURA images on disk vs manifest", f"{A['per_source']['agami']['files_on_disk']} vs {A['per_source']['agami']['rows']}; {A['per_source']['fatura']['files_on_disk']} vs {A['per_source']['fatura']['rows']}"],
    ["synthetic rows marked eval_eligible / real rows not eval_eligible", f"{B['synthetic_with_eval_eligible']} / {B['real_not_eval_eligible']}"], ["byte-identical file in both real and synthetic", B["real_synthetic_same_sha"]],
    ["approved rows; approved file == filtered manifest", f"{B['approved_rows']}; {B['approved_file_matches']}"], ["approved rows from conflict/unverified/blocked/not-acquired licences", len(B["approved_with_unresolved_licence"])], ["blocked / not-acquired sources present in manifest", len(B["blocked_or_not_acquired_sources_present"])],
    ["expense categories that collide with a document type", len(B["expense_category_equals_a_doc_type"])], ["original labels changed (inherited rows joined back to manifest.jsonl)", au["C_labels_preserved"].get("original_label_changed", 0)], ["rows without a mapping rule", au["C_labels_preserved"]["rows_without_mapping_rule"]],
    ["inherited real/older-synthetic splits differing from manifest.jsonl", au["C_labels_preserved"].get("split_differs_from_manifest_jsonl", 0) + 0], ["validator (v2.1 schema): errors / warnings / passed", f"{sum(map(len, va['errors'].values())) if va['errors'] else 0} / {len(va['warnings'])} / {va['passed']}"],
    ["frozen Task B test sha256 matches fd8bafb3ad13...", Dp["task_b_test_expected_prefix_fd8bafb3ad13"]], ["Task B V1 snapshot checksums", Dp["v1_snapshot_sha256sums"]], ["protected test docs (all still 'test')", f"{Dp['protected_test_docs']} ({Dp['protected_test_docs_all_still_test']})"]])
w("\nSources excluded from every approved manifest until a human clears their licence: " + ", ".join(f"`{k}`={v}" for k, v in st["excluded_by_source"].items()) + ". Rules: `config/approved_sources_v1.json`.\n")
w("## 2. Near-duplicate investigation (the 116 / 161 finding)\n")
ev2, ev21 = au["E_generated_leakage"]["v2_issuer_split"], au["E_generated_leakage"]["v2_1_template_split"]
w("**Cause: shared layouts (templates), not repeated documents, not shared issuers, and partly an audit limitation.** In v2 the generated split grouped by *issuer*, but every generated document has its own issuer, so `group_id` was effectively per document and could not protect against template reuse. All 3 seen layouts (A/B/C) of a document type were present in train, val and test; 100% of the seen-layout val/test pages therefore had a same-type, same-layout page in train (`same_template_in_train` below). No two files are byte-identical, and the text differs (names, amounts, dates): the OCR-text trigram Jaccard never reached 0.8. pHash 8x8 over-states similarity for pages that are mostly white text blocks, so it was complemented by pixel correlation and text overlap.\n")
rows = []
for name, d in (("v2 issuer split", ev2), ("v2.1 template-held-out", ev21)):
    for k, v in d.items(): rows.append([name, k.replace("|", " / "), v["n"], v["phash_le4"], v["ncc_ge_0.90"], v["ncc_ge_0.95"], v["trigram_jaccard_ge_0.6"], v["same_template_in_train"]])
table(["split version", "slice", "n pages", "pHash<=4 to a train page", "pixel NCC>=0.90", "NCC>=0.95", "text trigram Jaccard>=0.6", "same template in train"], rows)
w(f"\nAffected in v2: all 11 generated types x layouts A/B/C (val 155, test 161 pages). Layout D (174 test pages) was never affected. v2.1 holds out whole templates (layout D = test; one rotating layout of A/B/C per type = val; the other two = train): `same_template_in_train` is 0 for every val/test page and no template spans splits. Residual similarity (NCC>=0.90 for ~36% of val pages) comes from different layouts sharing a white-page text-block look, and Jaccard>=0.6 from the generator's shared wording per document type - both cannot be removed by splitting.\n")
w("**Second finding (older Task A/B synthetic data, NOT altered):** `synthetic_in` (2,430 project-generated bills) is split document-by-document from a single template family. " + f"Val: {si['val']['le4']}/{si['val']['n']} pages are pHash<=4 from a train page ({si['val']['identical']} at distance 0); test: {si['test']['le4']}/{si['test']['n']} ({si['test']['identical']} at distance 0); pixel NCC>=0.95: {si['ncc_and_text']['val']['ncc_ge_0_95']}/243 val, {si['ncc_and_text']['test']['ncc_ge_0_95']}/243 test (median text Jaccard ~0.5). "
  "These 243 test documents are inside the protected Task A, document_type and Task B test files (v2 had not flagged them; v2.1 now sets `in_protected_task_test` for 814 docs). The protected splits were **not** changed. Consequence: any Task A/B metric that includes these documents is optimistic; recomputing the metrics on the real-only subset is recommended (not done here - protected evaluation).\n")
w("## 3. Split corrections in v2.1 (v2 files untouched)\n")
table(["change", "scope", "why"], [["generated documents: template-held-out splits, `group_id` = template", f"synthgen_v1 ({sum(v for k, v in st['splits_changed'].items() if k.startswith('synthgen'))} docs moved)", "issuer grouping did not stop same-layout leakage"], ["Agami split by template (Scanned_Type2 val, Digital_Type2 test, others train)", f"agami ({sum(v for k, v in st['splits_changed'].items() if k.startswith('agami'))} docs moved)", "v2 had no val/test for bank statements"],
    ["derived tax labels by subtype (health -> 80D only, life -> 80C only; EV documents -> no loan-interest candidate)", f"{st['tax_corrected']} docs corrected, {st['tax_flagged']} flagged with `tax_mapping_note`", "v2 attached 80D+80C to every insurance receipt and loan-interest to every EV document"],
    ["`in_protected_task_test` extended to every doc in the frozen test files", f"{st['protected_flag_added']} docs flagged", "older synthetic test docs are in the protected test"], ["approval gate `approved_for_training` / `approval_tier`", f"{st['approved']} approved, {st['excluded']} excluded", "unresolved licences stay out"],
    ["OCR-cue cross-check of collection-rule labels -> `flagged_for_review`", f"{sum(st['flagged_by_source_type'].values())} flagged; queue of {st['queue_size']} (`mapping_review_queue_v2_1.jsonl`)", "ambiguous mappings are marked, not assumed"]])
w("\nReal splits (including all protected test documents) are identical to `manifest.jsonl`. New files: `doc_type_manifest_v2_1.jsonl`, `doc_type_v2_1_{real,synthetic}.jsonl`, `doc_type_v2_1_splits/`, `doc_type_v2_1_approved/`, `config/doc_type_schema_v2_1.json`, `config/approved_sources_v1.json`.\n")
w("## 4. Label-mapping review\n\nThe three axes stay separate (document type / Task A expense category / derived tax-evidence candidates; no expense category equals a document type; eligibility is only `pending_verification` or `not_applicable`). Every real label except the `rvl_cdip` and `in_financial` source labels is a collection-rule mapping marked `needs_mapping_review` (5,052 rows); " + f"{sum(st['flagged_by_source_type'].values())} of them contradict their own OCR text cues and are `flagged_for_review`. Known ambiguities: receipt vs invoice vs hotel/fuel/medical/travel (a hotel receipt can be `receipt` or `hotel_bill`), `in_financial` utility rows without a utility subtype, real `invoice` rows that mention rent, and EV/loan/school-fee/rental-agreement tax candidates (see `tax_mapping_note`). A human must resolve the queue before any label is called verified.\n")
w("## 5. Baseline experiment (`reports/doc_type/experiments_v3/tfidf_baseline_v2_1.json`)\n\nTF-IDF (char 2-5 + word 1-2) + logistic regression (C=10, balanced; fixed beforehand, nothing tuned), OCR text only, approved data only, generator watermark stripped. Task A model, V1 snapshot, frozen test and V2 annotation were not touched; the real test split was read **once** at the end (section 5.4).\n")
w("### 5.1 Counts\n"); table(["set", "documents"], [["real train (cord, my_receipts, receiptbench, manual_in, rvl_cdip, in_grocery_gst, invoices_pt)", C["train_real"]], ["real val", C["val_real"]], ["synthetic train (synthgen_v1, synthetic_in, fatura, agami)", C["train_synthetic"]], ["synthetic val, held-out templates (synthetic_in excluded)", C["val_synthetic"]]] + [[f"synthetic test slice: {k}", v] for k, v in C["test_synthetic_slices"].items()])
w("\nPer class (the 12 classes with **no approved real document**: " + ", ".join(bl["classes_without_any_approved_real_docs"]) + "; `cheque` has no approved data at all and was excluded):\n")
table(["class", "real train", "real val", "synthetic train", "synthetic val", "synthetic test"], [[c, v["real_train"], v["real_val"], v["synth_train"], v["synth_val"], v["synth_test"]] for c, v in C["per_class"].items()])
def pc_table(m):
    table(["class", "precision", "recall", "F1", "support"], [[c, v["precision"], v["recall"], v["f1"], v["support"]] for c, v in m["per_class"].items()])
w("\n### 5.2 Results by evaluation set\n"); G = bl["group_summary_real_backed_vs_synthetic_only_classes"]
table(["trained on -> evaluated on", "n", "accuracy", "macro-F1", "real-backed classes F1 (docs)", "synthetic-only classes F1 (docs)"],
      [[f"{k.split('|')[0]} -> {kk}", m["n"], m["accuracy"], m["macro_f1_classes_with_support"], f"{G[f'{k}|{kk}']['real_backed_classes']['macro_f1']} ({G[f'{k}|{kk}']['real_backed_classes']['n_docs']})", f"{G[f'{k}|{kk}']['synthetic_only_classes']['macro_f1']} ({G[f'{k}|{kk}']['synthetic_only_classes']['n_docs']})"] for k, v in E.items() for kk, m in v.items() if m])
w("\n**Real validation, combined model - per class:**\n"); pc_table(E["combined"]["real_val"]); w("\nTop confusions (true, predicted, count): " + str(E["combined"]["real_val"]["top_confusions"][:6]) + "\n\n**Real validation, real-only model - per class:**\n"); pc_table(E["real_only"]["real_val"])
w("\nFull confusion matrices for every row above are in the JSON report. Synthetic slices are all 1.0: every generated class is perfectly separable by generic vocabulary, even on an unseen layout, so the synthetic evaluation **cannot discriminate** between models (saturated). It shows the generator output is OCR-readable and class-consistent, nothing more.\n")
w("### 5.3 Leakage and shortcut diagnostics\n"); f = D["footer_kept_vs_stripped"]; mk = D["mask_class_titles_and_key_phrases"]
table(["diagnostic", "result"], [["watermark kept vs stripped (macro-F1): real val / layout D / synthetic val", f"{f['real_val']['macro_f1_footer_kept']} vs {f['real_val']['macro_f1_footer_stripped']} / {f['synthgen_layout_D']['macro_f1_footer_kept']} vs {f['synthgen_layout_D']['macro_f1_footer_stripped']} / {f['synthetic_val']['macro_f1_footer_kept']} vs {f['synthetic_val']['macro_f1_footer_stripped']}"],
   ["real val docs predicted into synthetic-only classes: plain / with watermark appended / primary model", f"{f['real_val_into_synthetic_only_classes']['footer_kept_model_plain_real_text']} / {f['real_val_into_synthetic_only_classes']['footer_kept_model_real_text_plus_synthetic_footer']} / {f['real_val_into_synthetic_only_classes']['primary_footer_stripped_model']}"],
   [f"class titles / key phrases masked ({mk['n_phrases']} phrases): layout D / synthetic val / real val", f"{mk['synthgen_layout_D']['macro_f1_masked']} / {mk['synthetic_val']['macro_f1_masked']} / {mk['real_val']['macro_f1_masked']} (unmasked {mk['synthgen_layout_D']['macro_f1_unmasked']} / {mk['synthetic_val']['macro_f1_unmasked']} / {mk['real_val']['macro_f1_unmasked']})"],
   ["all digits masked: real val / synthetic val / layout D", f"{D['mask_digits']['real_val']['macro_f1_masked']} / {D['mask_digits']['synthetic_val']['macro_f1_masked']} / {D['mask_digits']['synthgen_layout_D']['macro_f1_masked']}"],
   [f"{D['mask_generator_issuer_names']['n_names']} generator issuer names masked (layout D)", f"{D['mask_generator_issuer_names']['synthgen_layout_D']} (unmasked {D['mask_generator_issuer_names']['unmasked']})"], ["label-permutation control accuracy: real val / synthetic val (chance ~0.05)", f"{D['label_permutation_control']['real_val_accuracy']} / {D['label_permutation_control']['synthetic_val_accuracy']}"],
   ["source-only majority baseline accuracy: real val / synthetic val / layout D", f"{D['source_only_majority_baseline']['real_val']['accuracy']} / {D['source_only_majority_baseline']['synthetic_val']['accuracy']} / {D['source_only_majority_baseline']['synthgen_layout_D']['accuracy']}"],
   ["seen-layout (issuer-grouped) vs unseen layout D, synthgen-only model, accuracy", f"{D['seen_template_vs_heldout_template_synthgen_only_model']['seen_layouts_issuer_grouped_holdout']['accuracy']} vs {D['seen_template_vs_heldout_template_synthgen_only_model']['unseen_layout_D']['accuracy']}"],
   ["watermark-like features in the top-20 word features per class", str(D["suspect_generator_marker_features_in_top20"] or "none (one OCR-merged fragment 'cashier syntheticsample' in school_fee_receipt in the first run; stripping now tolerates OCR-dropped spaces)")], ["documents with watermark residue after stripping", f"{bl['footer_residue_after_stripping_docs']} (11 OCR-garbled footers, 2 genuine 'synthetic' words in real rvl_cdip docs)"]])
w("\nReading: the watermark, class titles, digits and issuer names are **not** what makes the synthetic slices easy; the synthetic classes differ from each other in ordinary vocabulary (landlord/tenant, lessor/lessee, EMI/borrower, kWh/charging...), which is by construction of the generator. The synthetic score therefore measures consistency with the generator's own wording, not robustness. Cross-domain transfer is poor in both directions: a real-only model scores accuracy " + str(E["real_only"]["synthetic_val_CROSS_DOMAIN"]["accuracy"]) + " on synthetic val (it has never seen those classes) and a synthetic-only model " + str(E["synthetic_only"]["real_val_CROSS_DOMAIN"]["accuracy"]) + " on real val (it labels most real receipts `invoice`). Adding the synthetic data to the real training set did **not** help the real classes (real val macro-F1 " + str(E["real_only"]["real_val"]["macro_f1_classes_with_support"]) + " real-only vs " + str(E["combined"]["real_val"]["macro_f1_classes_with_support"]) + " combined).\n")
w("### 5.4 Real test split, read once (frozen configuration, no feedback)\n"); T = bl.get("FINAL_real_test_single_read")
if T: w(f"n={T['n']} approved real test documents (the protected test split minus excluded sources). real-only: accuracy {T['real_only']['accuracy']}, macro-F1 {T['real_only']['macro_f1_classes_with_support']}; combined: accuracy {T['combined']['accuracy']}, macro-F1 {T['combined']['macro_f1_classes_with_support']} (8 classes; `medical_bill` has {T['combined']['per_class']['medical_bill']['support']} test doc). Consistent with validation; no decision was based on it.\n")
w("### 5.5 What this does and does not support\n\n- Supported: for the 8 real-backed classes a simple OCR-text model reaches ~0.91-0.93 accuracy, macro-F1 ~0.78-0.80 on 404 real val docs; small classes (medical_bill n=2, fuel_receipt n=13, utility_bill n=21) are too small for reliable per-class numbers; 100 Indian val docs: accuracy " + str(E["combined"]["real_val_Indian_only"]["accuracy"]) + ".\n- **Not supported:** any real-world claim for the 12 classes without approved real documents - the EV, meal voucher, rent receipt, rental agreement, school fee, insurance (80C/80D), investment (80C), loan interest, loan statement classes plus salary slip, form 16 and bank statement - which have synthetic-only train/val/test.\n")
(ROOT / "docs/DOC_TYPE_V2_1_AUDIT_AND_BASELINE.md").write_text("\n".join(L)); print("written", len(L))
